def test_runtime_is_monotonic_read_only_and_persistable():
 s=(ROOT/'scripts/progression/m245_special_pve_oracle_runtime.gd').read_text()
 for token in ['class_name M245SpecialPveOracleRuntime','if incoming_revision < revision: return false','LOCAL_PREVIEW','func export_state()','func import_state(state: Dictionary)','can_client_spend_resource() -> bool: return false','can_client_resolve_reward() -> bool: return false','can_client_advance_pity() -> bool: return false','can_client_claim_reward() -> bool: return false']: assert token in s

def test_factory_save_ui_and_admin_are_wired():
 f=(ROOT/'scripts/core/procedural_factory.gd').read_text(); gs=(ROOT/'scripts/core/game_state.gd').read_text(); ui=(ROOT/'scripts/ui/command_deck.gd').read_text(); reg=json.loads((ROOT/'data/admin_content_type_registry.json').read_text())['content_types']; assert 'M245SpecialPveOracleRuntime.new()' in f and 'special_pve_oracle.name = "SpecialPveOracle"' in f; assert '"m245_special_pve_oracle"' in gs and 'special_pve_oracle.import_state' in gs; assert 'SPECIAL PVE · ORAKEL / KOMPASS-SYSTEM' in ui and 'M245SpecialPveOracleCatalog.pool_card' in ui; assert 'oracle_reward_pool' in reg and 'special_pve_profile' in reg

def test_convergence_promoted_to_partial_and_bonusmap_rules_preserved():
 d=json.loads((ROOT/'data/m239_master_convergence_matrix.json').read_text()); by={x['domain']:x for x in d['domains']}; assert by['compass_cauldron_special_pve']['status']=='PARTIAL' and 'm245_fix' in by['compass_cauldron_special_pve']; wave=(ROOT/'scripts/world/bonusmap_wave_director.gd').read_text(); assert 'M177BonusMapBossRuntimeCatalog' in wave and 'player_sank_during_run' in wave
